def source_hashes():
    hashes = {name: hashlib.sha256((ROOT / 'web_r4' / name).read_bytes()).hexdigest() for name in FILES}
    hashes['scripts/browser_champion_insights.py'] = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    return hashes

