def run(env, output):
    """Run with INSIGHTS_BASE pointing to a loopback PC or public subpath server."""
    output = Path(output).resolve()
    output.mkdir(parents=True, exist_ok=True)
    before = source_hashes()
    with tempfile.TemporaryDirectory(prefix='champion-insights-browser-') as temp:
        script = Path(temp) / 'insights.cjs'
        script.write_text(BROWSER)
        process_env = dict(os.environ, **env, INSIGHTS_OUT=str(output))
        process_env.setdefault('NODE_PATH', '/opt/codex/cua_node/lib/node_modules')
        if 'CHROMIUM_EXECUTABLE' not in process_env and Path('/usr/bin/chromium').exists():
            process_env['CHROMIUM_EXECUTABLE'] = '/usr/bin/chromium'
        process = subprocess.run(['node',str(script)], cwd=ROOT,env=process_env,text=True,capture_output=True,timeout=120)
    (output / 'browser.log').write_text(process.stdout+process.stderr)
    receipt = json.loads((output/'browser-result.json').read_text()) if (output/'browser-result.json').exists() else {'passed':False}
    receipt.update(source_sha256=before, source_unchanged_during_run=before==source_hashes(), finished_at=datetime.now(timezone.utc).isoformat())
    receipt['passed'] = bool(receipt['passed'] and process.returncode==0 and receipt['source_unchanged_during_run'])
    (output/'runner.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'passed':receipt['passed'],'output':str(output)}))
    return 0 if receipt['passed'] else 1

class Quiet(SimpleHTTPRequestHandler):
    def log_message(self, *_args):
        pass

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output',type=Path,required=True)
    parser.add_argument('--base',help='Existing isolated loopback origin, optionally including /lol-coach')
    args=parser.parse_args()
    if args.base:
        return run({'INSIGHTS_BASE':args.base},args.output)
    server=ThreadingHTTPServer(('127.0.0.1',0),functools.partial(Quiet,directory=str(ROOT/'web_r4')))
    threading.Thread(target=server.serve_forever,daemon=True).start()
    try:
        return run({'INSIGHTS_BASE':'http://127.0.0.1:'+str(server.server_port)},args.output)
    finally:
        server.shutdown()
        server.server_close()

if __name__ == '__main__':
    raise SystemExit(main())
